function e(value){return String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');}
export function renderAccessUi({mode='login',message='',busy=false,backendReady=true}={}){
  const disabled=busy||!backendReady;const notice=message?`<p class="m26-auth-notice" role="status">${e(message)}</p>`:'';
  return `<main class="m26-auth-page"><section class="m26-auth-card"><img src="/public/isotipo-iberfit.png" alt="" aria-hidden="true"><p class="m26-eyebrow">IBERFIT</p><h1>Entrenamiento personal con criterio</h1><p>Diagnóstico, planificación, control y seguimiento.</p>${notice}<form data-auth-form="login" novalidate><label>Correo<input type="email" name="email" autocomplete="username" required></label><label>Contraseña<input type="password" name="password" autocomplete="current-password" required minlength="8"></label><button type="submit" class="m26-primary-action"${disabled?' disabled aria-disabled="true"':''}>${busy?'Confirmando…':'Entrar'}</button></form>${backendReady?'':'<p class="m26-notice is-warning">La configuración pública del backend no está activa en este host.</p>'}<small>El canario solo acepta cuentas QA autorizadas.</small></section></main>`;
}
